// Generated by the model-stats export (usage_counts.ts).
// Do not edit here; change the source and rerun the export.

import type { ClientModelName } from "./data/types.ts";
import { DollarAmount } from "./dollar_amount.ts";
import { TokenCount } from "./token_count.ts";

export const TOKEN_USAGE_KEYS = [
  "input",
  "uncached",
  "cached",
  "cache_write",
  "cache_write_1h",
  "thinking",
  "output",
] as const;

export type TokenUsageKey = (typeof TOKEN_USAGE_KEYS)[number];

/**
 * Immutable token counts with overlapping totals: input includes base input,
 * cache writes, and cache reads; uncached includes base input and cache writes.
 * CostUsageCounts separates those pricing categories for cost aggregation.
 *
 * M preserves the record's model name through the type system, for example
 * TokenUsageCounts<"gpt-4o">. Individual TokenCount values carry no model identity.
 */
export type TokenUsageCounts<M extends string = ClientModelName> = {
  readonly model: M;
  // Full prompt: base input + cache writes + cache reads.
  readonly input: TokenCount;
  // Input not served from cache: base input + cache writes.
  readonly uncached: TokenCount;
  /** Input served from a previously cached prefix. */
  readonly cached: TokenCount;
  // Slice of `output` attributed to reasoning tokens.
  readonly thinking?: TokenCount;
  /** Generated tokens, including the thinking portion when reported. */
  readonly output: TokenCount;
  /** Tokens charged at the model's default cache-write rate. Anthropic's
   * default covers five-minute retention; its one-hour writes are separate. */
  readonly cache_write?: TokenCount;
  // Tokens written to Anthropic's extended one-hour cache.
  readonly cache_write_1h?: TokenCount;
};

// Per-bucket dollar costs. Each field corresponds to exactly one pricing
// rate, so aggregating across calls (`sumCostUsageCounts`) preserves
// correct totals and no field is derivable by subtraction. Use
// `totalCost(cost)` for the grand total across all buckets.
export type CostUsageCounts = {
  /** Cost of input excluding cache reads and both cache-write categories. */
  base_input: DollarAmount;
  /** Cache-read tokens multiplied by the applicable cache-read price. */
  cached: DollarAmount;
  /** Default-retention cache-write cost; absent without that pricing category. */
  cache_write?: DollarAmount;
  /** One-hour cache-write cost; absent without that pricing category. */
  cache_write_1h?: DollarAmount;
  /** Generated-token cost, already including reasoning tokens. */
  output: DollarAmount;
  // Proportional slice of output attributed to reasoning/thinking, at the
  // same output rate. It is tracked separately for reporting and must not be
  // added to the output cost again.
  thinking?: DollarAmount;
};

/**
 * Cache prices divided by the model's base input price, stored alongside costs
 * so each record retains its pricing context. For example, 0.1 means one tenth
 * of base input price; 1.25 means a 25% premium. Write fields are absent when
 * the model has no corresponding cache-write price.
 */
export type CacheRateMultipliers = {
  cached_rate_multiplier?: number;
  cache_write_rate_multiplier?: number;
  cache_write_1h_rate_multiplier?: number;
};

const OPTIONAL_KEYS = ["thinking", "cache_write", "cache_write_1h"] as const;

export const EMPTY_COST_USAGE_COUNTS: CostUsageCounts = {
  base_input: DollarAmount.zero,
  cached: DollarAmount.zero,
  output: DollarAmount.zero,
};

export function emptyTokenUsageCounts<M extends string>(
  model: M
): TokenUsageCounts<M> {
  return {
    model,
    input: TokenCount.zero,
    uncached: TokenCount.zero,
    cached: TokenCount.zero,
    output: TokenCount.zero,
  };
}

// Thinking is already a slice of output; adding its cost here would count
// the same tokens twice.
export function totalCost(cost: CostUsageCounts): DollarAmount {
  const c = cost;
  return dollarValue(c.base_input)
    .plus(dollarValue(c.cached))
    .plus(dollarValue(c.cache_write))
    .plus(dollarValue(c.cache_write_1h))
    .plus(dollarValue(c.output));
}

// Look up a cost value by token-side bucket name. `TokenUsageCounts` has
// overlapping buckets (`input` is the prompt total; `uncached` includes cache
// writes) while `CostUsageCounts` is single-rate; this helper bridges them
// for display code that iterates token-side keys. `input` here mirrors the
// token-side meaning: prompt-side total, exclusive of output.
export function costForBucket(
  cost: CostUsageCounts,
  bucket: TokenUsageKey
): DollarAmount | undefined {
  const c = cost;
  switch (bucket) {
    case "input":
      return dollarValue(c.base_input)
        .plus(dollarValue(c.cached))
        .plus(dollarValue(c.cache_write))
        .plus(dollarValue(c.cache_write_1h));
    case "uncached":
      return dollarValue(c.base_input)
        .plus(dollarValue(c.cache_write))
        .plus(dollarValue(c.cache_write_1h));
    case "cached":
      return dollarValue(c.cached);
    case "cache_write":
      return c.cache_write === undefined
        ? undefined
        : dollarValue(c.cache_write);
    case "cache_write_1h":
      return c.cache_write_1h === undefined
        ? undefined
        : dollarValue(c.cache_write_1h);
    case "output":
      return dollarValue(c.output);
    case "thinking":
      return c.thinking === undefined ? undefined : dollarValue(c.thinking);
  }
}

function dollarValue(v: DollarAmount | number | undefined): DollarAmount {
  if (v === undefined) return DollarAmount.zero;
  if (typeof v === "number") return DollarAmount.value(v);
  return v;
}

export function sumTokenUsageCountsForDisplay<M extends string>(
  model: M,
  items: TokenUsageCounts[]
): TokenUsageCounts<M> {
  if (items.length === 0) return emptyTokenUsageCounts(model);

  const optional: {
    thinking?: TokenCount;
    cache_write?: TokenCount;
    cache_write_1h?: TokenCount;
  } = {};
  for (const key of OPTIONAL_KEYS) {
    const values = items
      .map((item) => item[key])
      .filter((value) => value !== undefined);
    if (values.length > 0) {
      optional[key] = TokenCount.sum(values);
    }
  }
  return {
    model,
    input: TokenCount.sum(items.map((item) => item.input)),
    uncached: TokenCount.sum(items.map((item) => item.uncached)),
    cached: TokenCount.sum(items.map((item) => item.cached)),
    output: TokenCount.sum(items.map((item) => item.output)),
    ...optional,
  };
}

export function sumCostUsageCounts(items: CostUsageCounts[]): CostUsageCounts {
  if (items.length === 0) return EMPTY_COST_USAGE_COUNTS;

  const result: CostUsageCounts = {
    base_input: DollarAmount.sum(items.map((item) => item.base_input)),
    cached: DollarAmount.sum(items.map((item) => item.cached)),
    output: DollarAmount.sum(items.map((item) => item.output)),
  };
  for (const key of OPTIONAL_KEYS) {
    const values = items
      .map((item) => item[key])
      .filter((value) => value !== undefined);
    if (values.length > 0) {
      result[key] = DollarAmount.sum(values);
    }
  }
  return result;
}
